-- LOCAL aggregate routes, region registry version 20260701.
-- Election is over the eligible full history BEFORE date/category/dimensions. No raw-row budget or cache.
-- Existing raw RPCs remain available for compatible Edge rollback.
begin;
create table private.analytics_region_tokens(token text primary key,code text not null);
create table private.analytics_region_names(key text primary key,code text not null);
create table private.analytics_region_splits(key text primary key,codes text[] not null);
create table private.analytics_region_geometry(code text primary key,geometry jsonb not null);
revoke all on private.analytics_region_tokens,private.analytics_region_names,private.analytics_region_splits,private.analytics_region_geometry from public,anon,authenticated;

create function private.analytics_in_ring(p_lng double precision,p_lat double precision,p_ring jsonb)
returns boolean language plpgsql immutable set search_path='' as $$
declare inside boolean:=false; n integer:=jsonb_array_length(p_ring); j integer:=n-1;
 xi double precision;yi double precision;xj double precision;yj double precision;
begin
 for i in 0..n-1 loop
   xi:=(p_ring->i->>0)::double precision; yi:=(p_ring->i->>1)::double precision;
   xj:=(p_ring->j->>0)::double precision; yj:=(p_ring->j->>1)::double precision;
   if (yi>p_lat)<>(yj>p_lat) then
     if p_lng<((xj-xi)*(p_lat-yi))/(yj-yi)+xi then inside:=not inside; end if;
   end if;
   j:=i;
 end loop;
 return inside;
end;$$;
create function private.analytics_in_polygon(p_lng double precision,p_lat double precision,p_rings jsonb)
returns boolean language plpgsql immutable set search_path='' as $$
begin
 if not private.analytics_in_ring(p_lng,p_lat,p_rings->0) then return false; end if;
 for i in 1..jsonb_array_length(p_rings)-1 loop
   if private.analytics_in_ring(p_lng,p_lat,p_rings->i) then return false; end if;
 end loop;
 return true;
end;$$;
create function private.analytics_region(p_key text,p_lat double precision,p_lng double precision)
returns text language plpgsql stable security definer set search_path='' as $$
declare tokens text[];sido text;v_code text;codes text[];g jsonb;poly jsonb;
begin
 if p_key is null then return null; end if;
 tokens:=regexp_split_to_array(btrim(p_key),'\s+');
 if cardinality(tokens)<2 then return null;end if;
 select t.code into sido from private.analytics_region_tokens t where t.token=tokens[1];
 if sido is null then return null;end if;
 if sido='36' then return '36110';end if;
 select s.codes into codes from private.analytics_region_splits s where s.key=sido||'|'||tokens[2];
 if codes is not null then
   if p_lat is null or p_lng is null then return null;end if;
   foreach v_code in array codes loop
     select geometry into g from private.analytics_region_geometry where analytics_region_geometry.code=v_code;
     if g->>'type'='Polygon' then
       if private.analytics_in_polygon(p_lng,p_lat,g->'coordinates') then return v_code;end if;
     else
       for poly in select value from jsonb_array_elements(g->'coordinates') loop
         if private.analytics_in_polygon(p_lng,p_lat,poly) then return v_code;end if;
       end loop;
     end if;
   end loop;
   return null;
 end if;
 select t.code into v_code from private.analytics_region_names t where t.key=sido||'|'||tokens[2];
 return v_code;
end;$$;

create function private.analytics_law(p_raw text)
returns text language plpgsql immutable set search_path='' as $$
declare t text:=btrim(p_raw);m text[];
begin
 if t is null or t='' then return null;end if;
 m:=regexp_match(t,'^([가-힣·\s]{1,60}?법)\s*제\s*0*([0-9]+)\s*조(?:\s*의\s*0*([0-9]+))?(?:\s*제?\s*[0-9]{1,3}\s*항)?$');
 if m is null then return t;end if;
 return regexp_replace(m[1],'\s+','','g')||' 제'||m[2]||'조'||case when m[3] is null then '' else '의'||m[3] end;
end;$$;

-- Only aggregate consumers use this relation. It is never granted to browser roles and never serialized as facts.
create function private.analytics_rollup_source(p_scope jsonb)
returns table(identity text,report_date date,completed_date date,category text,status text,disposition text,
 agency_key text,agency_name text,manager_key text,manager_name text,law text,amount_won bigint,rating integer)
language sql stable security definer set search_path='' set work_mem='32MB' as $$
 with grants as materialized (
   select g.grant_id,g.user_id,
     bool_or(d.amounts_public) as amounts_public,bool_or(d.violation_law_public) as law_public,bool_or(d.rating_public) as rating_public
   from private.community_consent_grants g
   join private.contributor_profiles c on c.user_id=g.user_id and c.status='active'
   join private.community_consent_grants a on a.lineage_id=g.lineage_id and a.user_id=g.user_id and a.revoked_at is null
   left join private.community_policy_disclosures d on d.version=a.policy_version
   group by g.grant_id,g.user_id
 ), candidates as (
   -- A safe candidate superset, including earlier observations. No grouping/election within the period.
   select distinct f.source_report_key from private.community_report_facts f
   join grants g on g.grant_id=f.consent_grant_id and g.user_id=f.contributor_id
   where f.public_state='completed'
     and (case p_scope->>'date_basis' when 'report_date' then f.report_date else f.completed_date end)
       between (p_scope->>'start')::date and (p_scope->>'end')::date
     and (p_scope->>'category'='all' or f.category=p_scope->>'category')
     and (p_scope->>'agency_key' is null or f.agency_key=p_scope->>'agency_key')
     and (p_scope->>'manager_key' is null or f.manager_key=p_scope->>'manager_key')
 ), observations as materialized (
   select f.source_report_key collate "C" as source_report_key,f.report_number collate "C" as report_number,
     f.payload_sha256 collate "C" as payload_sha256,f.contributor_id,f.answer_accepted_at,f.first_accepted_at,
     f.report_date,f.completed_date,f.category,f.status,f.disposition,f.agency_key,
     coalesce(nullif(f.agency_current_name,''),nullif(f.agency_name,''),'기관 정보 없음') as agency_name,
     f.manager_key,f.manager_name,f.region_code,f.lat,f.lng,
     case when g.law_public then f.violation_law else null end as law,
     case when g.rating_public then f.rating else null end as rating,
     case when g.amounts_public and f.amount_kind='fine' and f.disposition='fine' and f.status in ('accepted','partial')
       then f.amount_confirmed_won else null end as amount_won
   from private.community_report_facts f join grants g on g.grant_id=f.consent_grant_id and g.user_id=f.contributor_id
   where f.public_state='completed' and f.source_report_key in (select source_report_key from candidates)
 ), key_numbers as (
   select distinct on(source_report_key) source_report_key,report_number as key_number from observations
   where report_number is not null order by source_report_key,first_accepted_at,contributor_id
 ), identified as (
   select o.*,o.source_report_key||'|'||coalesce(o.report_number,k.key_number,'legacy') as rid,
     max(o.answer_accepted_at) over(partition by (o.source_report_key||'|'||coalesce(o.report_number,k.key_number,'legacy')),o.payload_sha256) as answer_time
   from observations o left join key_numbers k using(source_report_key)
 ), elected as (
   select i.*,row_number() over(partition by rid order by answer_time desc,completed_date desc nulls last,first_accepted_at,contributor_id) as rn
   from identified i
 ) select e.rid,e.report_date,e.completed_date,e.category,e.status,e.disposition,e.agency_key,e.agency_name,e.manager_key,e.manager_name,
   private.analytics_law(e.law),e.amount_won,e.rating::integer
 from elected e where e.rn=1
   and (case p_scope->>'date_basis' when 'report_date' then e.report_date else e.completed_date end)
     between (p_scope->>'start')::date and (p_scope->>'end')::date
   and (p_scope->>'category'='all' or e.category=p_scope->>'category')
   and (p_scope->>'agency_key' is null or e.agency_key=p_scope->>'agency_key')
   and (p_scope->>'manager_key' is null or e.manager_key=p_scope->>'manager_key')
   and (p_scope->>'region_code' is null or private.analytics_region(e.region_code,e.lat,e.lng) like (p_scope->>'region_code')||'%')
   and (p_scope->>'law' is null or case when p_scope->>'law'='__none__' then private.analytics_law(e.law) is null else private.analytics_law(e.law)=private.analytics_law(p_scope->>'law') end)
   and (p_scope->'bbox'='null'::jsonb or not p_scope?'bbox' or (e.lat is not null and e.lng between (p_scope->'bbox'->>0)::double precision and (p_scope->'bbox'->>2)::double precision
     and e.lat between (p_scope->'bbox'->>1)::double precision and (p_scope->'bbox'->>3)::double precision));
$$;

create function public.internal_analytics_rollup(p_scope jsonb,p_kind text,p_options jsonb)
returns jsonb language plpgsql stable security definer set search_path='' set work_mem='32MB' set statement_timeout='20s' set extra_float_digits='3' as $$
declare result jsonb;sort_column text:=p_options->'sort'->>'column';sort_value text:=p_options->'sort'->>'value';direction text:=p_options->'sort'->>'dir';
 page_no bigint:=(p_options->>'page')::bigint;page_size integer:=(p_options->>'page_size')::integer;needle text:=coalesce(p_options->>'q','');
begin
 if p_kind not in ('agency','manager','laws','series') or p_kind is null or p_scope->>'date_basis' not in ('report_date','completed_date')
   or (p_scope->>'start')::date>(p_scope->>'end')::date or p_scope->>'category' not in ('all','traffic','parking','other')
   or page_no<1 or page_size not between 1 and 100 or length(needle)>160 then raise exception 'INVALID_QUERY';end if;
 if p_options->>'expected_version' is distinct from (select dataset_version from private.analytics_state where singleton) then raise exception 'DATASET_CHANGED';end if;
 if p_kind<>'series' and (direction not in ('asc','desc') or not (
   (sort_column='completed' and sort_value='count') or (sort_column in ('accepted','partial','rejected','fine','warning','penalty') and sort_value in ('count','rate'))
   or (sort_column='duration' and sort_value in ('count','median')) or (sort_column='amount' and sort_value in ('count','sum'))
   or (sort_column='rating' and sort_value in ('count','mean')))) then raise exception 'INVALID_QUERY';end if;
 with source as (
   select s.*,case p_kind when 'agency' then coalesce(nullif(s.agency_key,''),'agency-unknown')
     when 'manager' then coalesce(nullif(s.agency_key,''),'agency-unknown')||':'||coalesce(nullif(s.manager_key,''),'manager-unknown')
     when 'laws' then coalesce(s.law,'')
     else to_char(case p_scope->>'date_basis' when 'report_date' then s.report_date else s.completed_date end,'YYYY-MM') end as group_key,
     case when s.completed_date>=s.report_date and s.status in ('accepted','partial','rejected','completed_unknown') then s.completed_date-s.report_date else null end as days
   from private.analytics_rollup_source(p_scope) s
   where p_kind='series' or s.status in ('accepted','partial','rejected','completed_unknown','withdrawn','transferred')
 ), groups as materialized (
   select group_key,count(*) as c,count(*) filter(where status in ('accepted','partial','rejected','completed_unknown','withdrawn','transferred')) as dc,
     (array_agg(agency_key order by identity collate "C"))[1] as agency_key,
     (array_agg(agency_name order by identity collate "C"))[1] as agency_name,
     (array_agg(manager_key order by identity collate "C"))[1] as manager_key,
     (array_agg(manager_name order by identity collate "C"))[1] as manager_name,
     (array_agg(law order by identity collate "C"))[1] as law,
     count(*) filter(where status='accepted') as accepted,count(*) filter(where status='partial') as partial,
     count(*) filter(where status='rejected') as rejected,count(*) filter(where disposition='fine' and status in ('accepted','partial','rejected','completed_unknown','withdrawn','transferred')) as fine,
     count(*) filter(where disposition='warning' and status in ('accepted','partial','rejected','completed_unknown','withdrawn','transferred')) as warning,count(*) filter(where disposition='penalty' and status in ('accepted','partial','rejected','completed_unknown','withdrawn','transferred')) as penalty,
     count(days) as duration_count,percentile_cont(0.5) within group(order by days) as median_days,sum(days)::double precision/nullif(count(days),0) as mean_days,
     count(amount_won) as amount_count,sum(amount_won) as sum_won,sum(amount_won)::double precision/nullif(count(amount_won),0) as mean_won,
     count(rating) filter(where status in ('accepted','partial','rejected','completed_unknown','withdrawn','transferred')) as rating_count,sum(rating) filter(where status in ('accepted','partial','rejected','completed_unknown','withdrawn','transferred'))::double precision/nullif(count(rating) filter(where status in ('accepted','partial','rejected','completed_unknown','withdrawn','transferred')),0) as mean_rating
   from source group by group_key
 ), values as (
   select g.*,case when btrim(agency_name)~'경찰(청|서)|지구대|파출소|치안센터|경찰대학|경찰교육원|경찰인재개발원|경찰수사연수원' then 'police'
     when agency_key like 'inst:%' or btrim(agency_name)~'(특별시|광역시|특별자치시|특별자치도|도|시|군|구)(청)?$|(시청|구청|군청|도청|공사|공단|사업소|관리소|주민센터|행정복지센터)$' then 'non_police' else 'unknown' end as agency_type,
     jsonb_build_object('accepted',accepted,'partial',partial,'rejected',rejected,'result_known',accepted+partial+rejected,'result_unknown',dc-accepted-partial-rejected) as outcomes,
     jsonb_build_object('fine_count',fine,'confirmed_count',amount_count,'sum_won',sum_won,'mean_won',mean_won) as amount,
     jsonb_build_object('count',duration_count,'median_days',median_days,'mean_days',mean_days) as duration,
     jsonb_build_object('count',rating_count,'mean',mean_rating) as rating,
     case p_kind when 'laws' then coalesce(law,'법규 미상') else agency_name||case when p_kind='manager' then coalesce(manager_name,'') else '' end end as display_name
   from groups g
 ), filtered as (
   select v.*,
     case sort_column when 'completed' then c::numeric when 'accepted' then accepted::numeric when 'partial' then partial::numeric when 'rejected' then rejected::numeric
       when 'fine' then fine::numeric when 'warning' then warning::numeric when 'penalty' then case when p_kind='laws' then penalty::numeric else null end
       when 'duration' then case when p_kind='laws' then null when sort_value='count' then duration_count::numeric else median_days::numeric end
       when 'amount' then case when sort_value='count' then amount_count::numeric else sum_won::numeric end
       when 'rating' then case when sort_value='count' then rating_count::numeric else mean_rating::text::numeric end end as num,
     case when sort_value='rate' then case when sort_column in ('accepted','partial','rejected') then nullif(accepted+partial+rejected,0) else c end else 1 end as den
   from values v where (p_options->>'agency_type' is null or v.agency_type=p_options->>'agency_type')
     and (needle='' or case when p_kind='laws' then strpos(v.display_name,needle)>0 else strpos(v.agency_name,needle)>0 or strpos(coalesce(v.manager_name,''),needle)>0 end)
 ), ordered as (
   select f.*,row_number() over(order by
     case when direction='asc' then div(num::numeric*10000000000000000000000000000000000000000::numeric,den::numeric) end asc nulls last,
     case when direction='desc' then div(num::numeric*10000000000000000000000000000000000000000::numeric,den::numeric) end desc nulls last,
     display_name collate "ko-x-icu",case when p_kind='laws' then coalesce(law,U&'\FFFF') else group_key end collate "C") as ord
   from filtered f
 ), page as (
   select o.ord,case when p_kind='laws' then jsonb_build_object('law',law,'completed_count',c,'outcomes',outcomes,
       'accept_rate',accepted::double precision*100/nullif(accepted+partial+rejected,0),'partial_rate',partial::double precision*100/nullif(accepted+partial+rejected,0),
       'fine_count',fine,'fine_rate',fine::double precision*100/nullif(c,0),'penalty_count',penalty,'warning_count',warning,'fine_amount',amount,'rating',rating)
     when p_kind='series' then jsonb_build_object('month',group_key,'report_count',c,'completed_count',dc,'fine_count',fine,
       'outcomes',outcomes,'duration',duration,'fine_amount',amount,'rating',rating)
     else jsonb_build_object('key',group_key,'agency_key',agency_key,'manager_key',case when p_kind='manager' then manager_key else null end,
       'agency_name',agency_name,'manager_name',case when p_kind='manager' then manager_name else null end,'agency_type',agency_type,
       'completed_count',c,'outcomes',outcomes,'fine_count',fine,'warning_count',warning,'duration',duration,'fine_amount',amount,'rating',rating) end as value
   from ordered o where p_kind='series' or (o.ord>(page_no-1)*page_size and o.ord<=page_no*page_size)
 ) select jsonb_build_object('items',coalesce((select jsonb_agg(value order by ord) from page),'[]'::jsonb),
   'total_rows',(select count(*) from filtered),
   'names',case when p_kind='manager' then coalesce((select jsonb_agg(jsonb_build_object('key',group_key,'agency_name',agency_name,'manager_name',manager_name) order by group_key collate "C") from groups),'[]'::jsonb) else '[]'::jsonb end)
 into result;
 return result;
end;$$;

revoke all on function private.analytics_in_ring(double precision,double precision,jsonb),private.analytics_in_polygon(double precision,double precision,jsonb),
 private.analytics_region(text,double precision,double precision),private.analytics_law(text),private.analytics_rollup_source(jsonb),public.internal_analytics_rollup(jsonb,text,jsonb) from public,anon,authenticated;
grant execute on function public.internal_analytics_rollup(jsonb,text,jsonb) to service_role;
commit;
